const r = await tools.exec_command({"cmd":"python - <<'PY'
import sympy as s, pandas as pd, re
n=pd.read_csv('data/network.tsv',sep='\t'); mets=[]
for eq in n.equation:
 for z in re.findall(r'([A-Za-z0-9]+(?:\.ext)?)',eq):
  if z not in ['CO2'] and not z.isdigit() and z not in mets: mets.append(z)
intra=[x for x in mets if not x.endswith('.ext')]
S=s.zeros(len(intra),len(n))
for j,eq in enumerate(n.equation):
 a,b=re.split(r' -> | <=> ',eq)
 for side,sgn in [(a,-1),(b,1)]:
  for term in side.split(' + '):
   q=term.split(); coef=int(q[0]) if len(q)>1 and q[0].isdigit() else 1; met=q[-1]
   if met in intra:S[intra.index(met),j]+=sgn*coef
print('mets',intra);print('rank/null',S.rank(),len(n)-S.rank())
sol=s.linsolve((S,s.zeros(len(intra),1)),*s.symbols('v:'+str(len(n))))
for rid,expr in zip(n.reaction_id,list(sol)[0]): print(rid,expr)
PY","workdir":"/root","yield_time_ms":10000,"max_output_tokens":20000});
